
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hse12s_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hse12s", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.583967318612820e+00, -2.536180912057463e+00, -2.469285239101376e+00, -2.376755535381732e+00, -2.250965298509646e+00, -2.084169058774609e+00, -1.870741605812760e+00, -1.610817614730004e+00, -1.313094828164879e+00, -9.941753156197378e-01, -6.893677506727350e-01, -4.946942551259486e-01, -4.399114096556845e-01, -3.691007510217685e-01, -2.786597469634460e-01, -1.900042947277793e-01, -1.165548047010575e-01, -4.933381146430491e-02, -1.081733186569940e-02, -1.216210562357123e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


